/// Raven `BotWeaponCanLead`.
///
/// Source: `oracle/oracle/codemp/game/ai_main.c:4570-4604`
pub fn BotWeaponCanLead(
    bs: *mut bot_state_t,
) -> f32 {
    let weap = unsafe { (*bs).cur_ps.weapon };
    if weap == WP_BRYAR_PISTOL {
        return 0.5;
    }
    if weap == WP_BLASTER {
        return 0.35;
    }
    if weap == WP_BOWCASTER {
        return 0.5;
    }
    if weap == WP_REPEATER {
        return 0.45;
    }
    if weap == WP_THERMAL {
        return 0.5;
    }
    if weap == WP_DEMP2 {
        return 0.35;
    }
    if weap == WP_ROCKET_LAUNCHER {
        return 0.7;
    }
    0.0
}

