pub fn BotWeaponBlockable(
    weapon: c_int,
) -> c_int {
    match weapon {
        WP_STUN_BATON | WP_MELEE => 0,
        WP_DISRUPTOR => 0,
        WP_DEMP2 => 0,
        WP_ROCKET_LAUNCHER => 0,
        WP_THERMAL => 0,
        WP_TRIP_MINE => 0,
        WP_DET_PACK => 0,
        _ => 1,
    }
}

